// v1.7.19 — owner, 12 Nov 2026 (Sydney time): “i knew there would be this issues so thats why i asked you to create the autoplay to test
// all the scenarios, now based on what you learn and what you have audited, incorporate it in the autoplay”.
//
// “Rà soát 12/11” in Tự chạy thử: one scenario per family of problems the whole-app audit of 12 Nov 2026 found
// (docs/reviews/audit-20261112/), so the app would have caught them by itself. Each one does the job through the screens, the way
// the family does, and checks the rule the audit taught (AGENTS.md rules 24, 29–34):
//  • the family's own settings — a menu week that starts on Saturday or on Sunday, English, money in đồng, a dish with its own yield
//    and guests (rule 34);
//  • nothing chosen for the family — no “g”, no $0, no first item of a list (rule 32);
//  • every number on a control equals what it opens, and nothing opens empty without saying why and what to do (rule 31), with the
//    sample data and with an emptied kitchen;
//  • what the family adds, they can edit and undo (rule 31), the dish sheet as decided on 12 Nov;
//  • the decisions of 12 Nov: spoon amounts are notes, bought extras count on the list, receipt lots get an editable use-by, meal
//    times drive the cooking time;
//  • and, after every scenario (old and new), the round trip of rule 33 (ladybug-autoplay.ts roundTrip).
// Same safety as every scenario: a sample family (or a copy of the family's data) in memory, nothing saved, synced or sent; only
// the existing failure report goes to Góp ý.
(function(){
 const G:any=globalThis;const A=G.bepAutoplay;if(!A?.kit)return;const k=A.kit,{tap,type,waitFor,waitGone,find,expect,go,part,skip,sleep,aT}=k;
 // ── what the checks read (the same accessors the app uses: never a Monday assumption) ─────────────────────────────────────
 const ing=(id:string)=>(INGREDIENTS as any)[id];
 const idOf=(...names:string[])=>{for(const n of names){const id=Object.keys(INGREDIENTS).find(x=>String(ing(x)[0]).toLowerCase()===n.toLowerCase());if(id)return id}return ''};
 const today=()=>sydneyDate();
 const mealOf=(d:string,t:string)=>dayAt(state,d)?.[t];
 const rowsOf=(start:string,end:string)=>shopping(state,planWeek(state,planStartOf(state,start)),start,end) as any[];
 const rowOf=(id:string,start:string,end:string)=>rowsOf(start,end).find((r:any)=>r.id===id);
 const stockOf=(id:string)=>typeof stock==='function'?+stock(state,id):state.pantry.filter((p:any)=>p.ingredient===id).reduce((n:number,p:any)=>n+(+p.qty||0),0);
 const near=(a:number,b:number,tol=0.6)=>Math.abs(a-b)<=Math.max(tol,Math.abs(b)*0.002);
 const setVal=(el:any,v:string)=>{el.value=v;el.dispatchEvent(new Event('input',{bubbles:true}));el.dispatchEvent(new Event('change',{bubbles:true}))};
 const mainText=()=>(document.getElementById('main') as HTMLElement).innerText;
 const modalText=()=>(document.getElementById('modal-root') as HTMLElement)?.innerText||'';
 const mondayKeysOnly=()=>Object.keys(state.weeks||{}).filter(x=>/^\d{4}-\d{2}-\d{2}$/.test(x)&&monday(x)!==x);
 const ascii=(s:string)=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/gi,'d').toUpperCase();
 async function pick(sel:string,value:string){const e=await waitFor(sel) as HTMLSelectElement;if(k.watch()){e.scrollIntoView({block:'center'});await sleep(300)}setVal(e,value);await sleep(k.watch()?350:60);return e}
 async function submit(id:string){const b=find(`#modal-root [data-action="submit-form"][data-id="${id}"]`)||find(`#${id} button[type="submit"]`);if(b)await tap(b);else (document.getElementById(id) as HTMLFormElement)?.requestSubmit();await sleep(250)}
 async function undo(){const b=await waitFor('#undo-bar button',3000);await tap(b,{label:aT('Hoàn tác','Undo')});await sleep(200)}
 // the shared unit picker, the way a person picks a unit (unit-picker.ts)
 async function pickUnit(btn:string,unit:string){await tap(btn);await waitFor('#unit-sheet-layer .unit-chip');let chip=find(`#unit-sheet-layer .unit-chip[data-unit-choice="${unit}"]`);if(!chip){const all=find('#unit-sheet-layer [data-unit-action="show-all"]');if(all){await tap(all);await sleep(120)}chip=await waitFor(`#unit-sheet-layer .unit-chip[data-unit-choice="${unit}"]`)}await tap(chip!);await tap('#unit-sheet-layer [data-unit-sheet-act="save"]');await sleep(120)}
 // write a family dish through “Viết món ăn”, each unit picked in the unit picker
 async function writeDish(name:string,rows:[string,number,string][],{time=30,yieldN=4}={}){
  await go('recipes');await tap('#main [data-fm="new"]');const form=await waitFor('#family-recipe-form');
  await type('#family-recipe-form [name="name"]',name);await type('#family-recipe-form [name="time"]',String(time));await type('#family-recipe-form [name="yield"]',String(yieldN));
  for(let i=0;i<rows.length;i++){let li=form.querySelectorAll('.rc-ing-row')[i] as HTMLElement|undefined;if(!li){await tap('#family-recipe-form [data-rci="add"]');await sleep(120);li=form.querySelectorAll('.rc-ing-row')[i] as HTMLElement|undefined}expect(li,aT('Không thêm được dòng nguyên liệu.','Could not add an ingredient row.'));
   const [id,qty,unit]=rows[i];setVal(li!.querySelector('.rc-ing-name-input'),String(ing(id)[0]));await sleep(60);setVal(li!.querySelector('.rc-ing-qty'),String(qty));const ub=li!.querySelector('.rc-ing-unit') as HTMLElement;if(ub.getAttribute('value')!==unit&&(ub as any).value!==unit)await pickUnit(`#${ub.id}`,unit)}
  const f=form as any;if(f.category&&!f.category.value)await pick('#family-recipe-form [name="category"]','main');if(f.protein&&!f.protein.value)await pick('#family-recipe-form [name="protein"]',f.protein.options[1]?.value||'');
  await submit('family-recipe-form');await waitGone('#family-recipe-form',6000);const r=state.recipes.find((x:any)=>x.name===name);expect(r,aT(`Món “${name}” không được lưu.`,`“${name}” was not saved.`));return r}
 // put a dish on a meal through the meal's “Thêm món ăn”
 async function addToMeal(date:string,meal:string,r:any){weekStart=planStartOf(state,date);await go('planner');weekStart=planStartOf(state,date);render();
  const b=await waitFor(`#main [data-fm="edit-meal"][data-date="${date}"][data-type="${meal}"]`);await tap(b);await waitFor('#family-meal-form');
  await type('#family-meal-form #meal-dish-search',r.name);const box=await waitFor(`#family-meal-form .family-select-row[data-id="${r.id}"] input[name="recipe"]`) as HTMLInputElement;if(!box.checked)await tap(box);
  await submit('family-meal-form');await waitGone('#family-meal-form',5000);expect(mealOf(date,meal).recipes.some((x:any)=>x.id===r.id),aT(`“${r.name}” chưa có trong bữa.`,`“${r.name}” is not on the meal.`))}
 async function everyoneHome(date:string,meal:string){const m=mealOf(date,meal);if(!m)return;let changed=false;for(const p of state.members)if(m.attendance?.[p.id]!=='home'){m.attendance={...(m.attendance||{}),[p.id]:'home'};changed=true}if(changed){save();render()}}
 // open the guests sheet for one meal from Today, as the family does (date and meal chips), and change the adults by `adults`
 async function guestsFor(date:string,meal:string,name:string,adults:number){selectedDate=date;weekStart=planStartOf(state,date);await go('today');selectedDate=date;render();await sleep(150);
  const s=find('#main .guest-shortcut');if(s)await tap(s);else guestSheet(date,meal);await waitFor('#modal-root #guest-groups');
  for(const [n,v] of [['from-date',date],['from-type',meal],['to-date',date],['to-type',meal]]){const c=find(`#modal-root [data-guest-pick="${n}"][data-v="${v}"]`);if(c&&c.getAttribute('aria-pressed')!=='true')await tap(c,{still:true})}
  if(!find('#modal-root [data-guest-name="0"]'))await tap('#modal-root [data-fm="guest-add"]');await type('#modal-root [data-guest-name="0"]',name);
  for(let i=0;i<adults;i++)await tap('#modal-root [data-guest-step="1"][data-k="adults"]',{still:i===0});
  await tap('#modal-root [data-fm="guests-save"]');await waitGone('#modal-root #guest-groups')}
 // a pretend receipt typed in (instead of the photo), its date, and each line matched by typing in the match box
 async function enterReceipt(text:string,{date='',match=[] as [RegExp,string,string][]}={}){await go('expenses');const nb=find('[data-feature="receipt-new"]');if(nb)await tap(nb);else newReceipt();await waitFor('#modal-root #receipt-raw');
  await type('#modal-root #receipt-raw',text);if(date)await type('#modal-root #receipt-date',date);await tap('#modal-root [data-feature="receipt-parse"]');await waitFor('#modal-root .receipt-line');
  for(const [re,id,q] of match){const line=[...document.querySelectorAll('#modal-root .receipt-line')].find(l=>re.test((l.querySelector('.receipt-label') as HTMLInputElement)?.value||'')) as HTMLElement;expect(line,aT(`Không đọc được dòng ${re.source}.`,`Line ${re.source} was not read.`));
   const sel=line.querySelector('select.receipt-match') as HTMLSelectElement;if(sel.value!==id){const i=line.dataset.index;await tap(line.querySelector('.rm-search') as HTMLElement);await type(`#modal-root .receipt-line[data-index="${i}"] .rm-search`,q);const o=await waitFor(`#modal-root .receipt-line[data-index="${i}"] .rm-opt[data-rm-value="${id}"]`);await tap(o)}expect(sel.value===id,aT(`Dòng ${re.source} chưa ghép được.`,`${re.source} not matched.`))}}
 async function saveReceipt(){const n0=state.receipts.length;await tap('#modal-root [data-feature="receipt-save"]');await sleep(350);if(find('#modal-root [data-feature="receipt-save"]'))await tap('#modal-root [data-feature="receipt-save"]');await sleep(350);expect(state.receipts.length===n0+1,aT('Hoá đơn chưa được lưu.','The receipt was not saved.'));return state.receipts[state.receipts.length-1]}
 // a menu for the week that holds `date`, in the family's own week (planned only when the week has no dishes yet)
 function ensureMenu(date:string){const S=planStartOf(state,date),days=[0,1,2,3,4,5,6].map(i=>addDays(S,i));if(!days.every(d=>MEAL_TYPES.some((t:string)=>dayAt(state,d)?.[t]?.recipes?.length))){familyGenerate(state,S,{sourceMode:'library'});save();render()}return{S,days}}
 const R=(id:string,vi:string,en:string,dvi:string,den:string,run:()=>Promise<void>)=>A.register({id,vi,en,dvi,den,run,audit:true});

 // ── 1–2. a menu week that starts on Saturday / on Sunday (audit B1, B2, C8; rule 34) ─────────────────────────────────────
 const WD:any={6:['thứ Bảy','Saturday'],0:['Chủ nhật','Sunday']};
 // a starting point a later step needs: required on the sample family; on a copy of the family's data a missing one ends the step quietly
 const needs=(ok:any,msg:string)=>{if(ok)return true;if(k.mode()==='real')return false;expect(false,msg);return false};
 async function weekMatrix(startDay:number){const [vi,en]=WD[startDay];let S='',days:string[]=[],d='',t='dinner',id='',q0=0;
  await part(aT(`Thực đơn → “Tuần bắt đầu” = ${vi}`,`Menu → “Week starts” = ${en}`),async()=>{await go('planner');await pick('#main #week-start-day',String(startDay));await sleep(150);
   expect(weekStartDay(state)===startDay,aT('Ngày bắt đầu tuần không được lưu.','The week start was not saved.'));expect(parseDate(weekStart).getDay()===startDay,aT(`Tuần đang xem bắt đầu ${weekStart}, không phải ${vi}.`,`The week in view starts ${weekStart}, not on ${en}.`))});
  // next week of the family: every day is still ahead, and it spans two Monday weeks
  await part(aT('Tuần sau của nhà mình có thực đơn','The family’s next week has a menu'),async()=>{({S,days}=ensureMenu(addDays(today(),7)));d=days.find(x=>monday(x)!==monday(S))!;t=MEAL_TYPES.find((x:string)=>mealOf(d,x)?.recipes?.length&&!mealOf(d,x).cooked)||'dinner';
   expect(mealOf(d,t)?.recipes?.length,aT(`Ngày ${d} chưa có bữa nào có món.`,`No meal with dishes on ${d}.`));expect(planWeek(state,S).days[d]===dayAt(state,d),aT('Thực đơn tuần đọc ngày khác chỗ lưu.','The menu week reads a day from somewhere else.'))});
  await part(aT('Có khách ngày giữa tuần (tuần thứ Hai khác)','Guests mid-week (another Monday week)'),async()=>{await everyoneHome(d,t);const s0=mealServings(mealOf(d,t),state);id=Object.keys(mealIngredients(mealOf(d,t),state)).find(x=>['g','ml'].includes(ing(x)?.[1]))||'';q0=+(rowOf(id,d,d)?.needed||0);
   await guestsFor(d,t,`Khách tuần ${vi} (thử)`,1);const m=mealOf(d,t);expect((m.guests||[]).some((g:any)=>g.name===`Khách tuần ${vi} (thử)`),aT(`Khách không được lưu vào bữa ngày ${d}.`,`The guests were not saved on the meal of ${d}.`));
   expect(!mondayKeysOnly().length,aT(`Khách được lưu vào bản sao tuần ${mondayKeysOnly().join(', ')}.`,`Guests were saved into a copy week ${mondayKeysOnly().join(', ')}.`));
   expect(near(mealServings(m,state),s0+2,0.01),aT(`Suất ăn ${mealServings(m,state)}, cần ${s0+2}.`,`Portions ${mealServings(m,state)}, expected ${s0+2}.`));
   if(id)expect(+(rowOf(id,d,d)?.needed||0)>q0,aT(`${ing(id)[0]} ngày đó không tăng theo khách (${Math.round(q0)}).`,`${id} that day did not rise with the guests (${q0}).`));
   weekStart=S;await go('planner');expect(planWeek(state,S).days[d][t].guests?.length,aT('Thực đơn tuần không thấy khách.','The weekly menu does not show the guests.'))});
  await part(aT('Đi chợ cả tuần: từ ngày đầu tuần của nhà, đủ 7 ngày, có phần của khách','Shopping for the week: from the family’s first day, 7 days, guests included'),async()=>{weekStart=S;selectedDate=S;await go('shopping');weekStart=S;render();if(shopRange!=='week')await pick('#main [data-change="shop-range"]','week');
   const [a,b]=shopDates();expect(a===S&&b===addDays(S,6),aT(`Danh sách đi chợ tính ${a} → ${b}, không phải ${S} → ${addDays(S,6)}.`,`The list covers ${a} → ${b}, not ${S} → ${addDays(S,6)}.`));
   // the week's list is the sum of its seven days, each read where it is stored (days of both Monday weeks, the guests' day too)
   const ids=[...new Set([id,...rowsOf(S,addDays(S,6)).filter((r:any)=>['g','ml'].includes(ing(r.id)?.[1])&&r.needed>0).map((r:any)=>r.id)].filter(Boolean))].slice(0,6);expect(ids.length,aT('Danh sách tuần trống.','The week’s list is empty.'));
   for(const x of ids){const want=days.reduce((n,dd)=>n+(+(rowOf(x,dd,dd)?.needed||0)),0),r=rowOf(x,S,addDays(S,6));expect(r&&near(+r.needed,want,1),aT(`${ing(x)[0]}: danh sách tuần cần ${r?Math.round(r.needed):0}, cộng 7 ngày là ${Math.round(want)}.`,`${x}: the week’s list needs ${r?r.needed:0}, the 7 days add up to ${want}.`))}
   if(id)expect(find(`#main [data-action="ingredient-detail"][data-id="${id}"]`)||(rowOf(id,S,addDays(S,6))?.missing||0)<=0,aT(`Trang Đi chợ không có ${ing(id)[0]}.`,`The shopping page does not show ${id}.`))});
  await part(aT('Tìm món đã lên cho ngày đó','Search finds the dish planned that day'),async()=>{/* v1.7.20: search shows the 6 nearest meals of a dish; pick the dish of that day with fewer than 6 nearer ones, so the check is about the week, not the list length */const near=(name:string)=>{let c=0;const t0=sydneyDate();for(let i=0;i<=28;i++){const x=addDays(t0,i);if(x>=d)break;for(const tt of MEAL_TYPES)if((mealOf(x,tt)?.recipes||[]).some((r:any)=>r.name===name))c++}return c};const dish=(mealOf(d,t).recipes as any[]).slice().sort((a:any,b:any)=>near(a.name)-near(b.name))[0];expect(near(dish.name)<6,aT(`Mọi món ngày ${d} đều có từ 6 bữa gần hơn.`,`Every dish on ${d} has 6 nearer meals.`));await go('today');await tap('#app-search');await type('#modal-root #app-search-input',String(dish.name));await waitFor('#modal-root .search-hit-row');
   const tag=`${+d.slice(8)}/${+d.slice(5,7)}`,hit=[...document.querySelectorAll('#modal-root .search-hit-row')].find(h=>(h as HTMLElement).innerText.includes(dish.name)&&(h as HTMLElement).innerText.includes(tag)) as HTMLElement|undefined;
   expect(hit,aT(`Tìm “${dish.name}” không thấy bữa ngày ${tag}.`,`Searching “${dish.name}” does not find the meal on ${tag}.`));await tap(hit!);await sleep(250);expect(selectedDate===d,aT(`Mở kết quả ra ngày ${selectedDate}, không phải ${d}.`,`The result opened ${selectedDate}, not ${d}.`));try{closeModal()}catch{}});
  await part(aT('Hoá đơn ngày đó → đánh dấu đã mua đúng tuần, Hoàn tác bỏ đúng','A receipt that day → bought in the right week; Undo takes it back'),async()=>{weekStart=S;selectedDate=d;
   const r0=rowsOf(S,addDays(S,6)).find((r:any)=>ing(r.id)?.[1]==='g'&&r.missing>0&&!r.bought&&!r.skip);if(!needs(r0,aT('Danh sách tuần không còn gì cần mua.','Nothing left to buy this week.')))return;
   const x=r0.id,m0=r0.missing,kg=Math.max(1,Math.ceil(m0/1000)),word=ascii(ing(x)[0]).split(/\s+/)[0];
   await enterReceipt(['COLES',`${ascii(ing(x)[0])} ${kg}KG 9.90`,'TOTAL 9.90'].join('\n'),{date:d,match:[[new RegExp(word,'i'),x,String(ing(x)[0])]]});await saveReceipt();
   const ap=await waitFor('#modal-root [data-rui="apply"]',4000);await tap(ap);await sleep(300);try{closeModal()}catch{}
   const r1=rowOf(x,S,addDays(S,6));expect(r1.bought||r1.missing<m0,aT(`${ing(x)[0]} vẫn cần mua ${Math.round(r1.missing)} sau hoá đơn ngày ${d}.`,`${x} still to buy after the receipt of ${d}.`));
   expect(!mondayKeysOnly().length,aT(`Hoá đơn ghi vào bản sao tuần ${mondayKeysOnly().join(', ')}.`,`The receipt wrote into a copy week ${mondayKeysOnly().join(', ')}.`));
   const u=find('.receipt-undo [data-rui="undo"]');expect(u,aT('Không có nút Hoàn tác sau khi cập nhật từ hoá đơn.','No Undo after updating from the receipt.'));await tap(u!);await sleep(250);
   const r2=rowOf(x,S,addDays(S,6));expect(!r2.bought&&near(r2.missing,m0,1),aT(`Hoàn tác xong ${ing(x)[0]} còn cần ${Math.round(r2.missing)}, không phải ${Math.round(m0)}.`,`After undo ${x} needs ${r2.missing}, not ${m0}.`))})}
 R('au-week-sat','Tuần bắt đầu thứ Bảy','Week starting on Saturday','Đặt tuần thực đơn bắt đầu thứ Bảy; khách vào đúng bữa, đi chợ đủ 7 ngày, tìm thấy món, hoá đơn ghi đúng tuần và hoàn tác được.','Start the menu week on Saturday; guests land on the right meal, shopping covers 7 days, search finds the dish, a receipt marks the right week and undoes.',()=>weekMatrix(6));
 R('au-week-sun','Tuần bắt đầu Chủ nhật','Week starting on Sunday','Như trên, với tuần bắt đầu Chủ nhật.','As above, with the week starting on Sunday.',()=>weekMatrix(0));

 // ── 3. English (audit D11–D17, B20, B22; rule 34) ───────────────────────────────────────────────────────────────────────
 const VI_ONLY=/[ăâđơưạảấầẩẫậắằẳẵặẹẻẽếềểễệỉịọỏốồổỗộớờởỡợụủứừửữựỳỵỷỹ]/i;
 // controls whose words come from the app (not the family's dish, ingredient or people names)
 function viLeftovers(root:Element|null){if(!root)return [];return ([...root.querySelectorAll('h1,h2,.btn,button.chip,[role="tab"],.section-mini,label')] as HTMLElement[]).filter(e=>k.visible(e)&&!e.closest('[data-user-content],.family-dish,.family-dish-row,.lib-card,.recipe-card,.shop-row .item-label,.inventory-card,.receipt-line,.mr-wrap,.guest-group,option')&&!e.hasAttribute('data-user-content'))
  .map(e=>{const c=e.cloneNode(true) as HTMLElement;c.querySelectorAll('[data-user-content],svg,select,.sr-only').forEach(x=>x.remove());return (c.textContent||'').replace(/\s+/g,' ').trim()}).filter(x=>x&&VI_ONLY.test(x)&&!state.members.some((p:any)=>x.includes(p.name)))}
 R('au-english','Tiếng Anh trên các màn hình chính','English on the main screens','Đổi sang English; nút, tab, tiêu đề ở Hôm nay, Thực đơn, Đi chợ, Tủ, Món ăn, Chi tiêu và các sheet hay dùng không còn chữ tiếng Việt; đổi lại được.','Switch to English; buttons, tabs and titles on Today, Menu, Shopping, Pantry, Recipes, Spending and the common sheets have no Vietnamese left; switching back works.',async()=>{
  let h0='';const lang0=typeof appLanguage!=='undefined'?appLanguage:'vi';
  await part(aT('Đổi sang English','Switch to English'),async()=>{await go('today');h0=(find('#main h1') as HTMLElement).innerText;if(lang0!=='en'){await tap('#app-language');await sleep(250)}expect(appLanguage==='en',aT('Không đổi được sang English.','Could not switch to English.'))});
  for(const v of ['today','planner','shopping','pantry','recipes','expenses'])await part(`English: ${v}`,async()=>{await go(v);await sleep(120);const bad=viLeftovers(document.getElementById('main'));expect(!bad.length,aT(`Còn chữ tiếng Việt: ${bad.slice(0,5).join(' | ')}`,`Vietnamese left: ${bad.slice(0,5).join(' | ')}`))});
  const sheets:[string,string,()=>Promise<any>][]=[['shopping','Đồ trong tủ / Pantry',async()=>{await tap('#main [data-action="check-pantry"]')}],['pantry','Thêm thực phẩm / Add pantry food',async()=>{await tap('#main [data-action="add-stock"]')}],['shopping','Mua thêm / Buy extra',async()=>{await tap('#main [data-action="add-extra"]')}]];
  for(const [v,label,open] of sheets)await part(`English: ${label}`,async()=>{await go(v);await open();await waitFor('#modal-root .modal');await sleep(120);const bad=viLeftovers(document.querySelector('#modal-root .modal'));closeModal();expect(!bad.length,aT(`Còn chữ tiếng Việt: ${bad.slice(0,5).join(' | ')}`,`Vietnamese left: ${bad.slice(0,5).join(' | ')}`))});
  // back to the language the family uses (from English: to Vietnamese and back), and the page follows each switch
  await part(aT('Đổi lại ngôn ngữ của nhà mình','Switch back to the family’s language'),async()=>{await go('today');const h1=(find('#main h1') as HTMLElement).innerText;await tap('#app-language');await sleep(250);expect(appLanguage==='vi',aT('Không đổi được sang tiếng Việt.','Could not switch to Vietnamese.'));expect((find('#main h1') as HTMLElement).innerText!==h1,aT('Đổi ngôn ngữ mà tiêu đề không đổi.','The title did not follow the switch.'));
   if(lang0==='en'){await tap('#app-language');await sleep(250)}expect(appLanguage===lang0,aT('Không đổi lại được.','Could not switch back.'));expect((find('#main h1') as HTMLElement).innerText===h0,aT('Tiêu đề Hôm nay không trở lại như trước.','The Today title did not come back.'))})});

 // ── 4. money in đồng (audit B13, C12, C13, C23; rule 34) ────────────────────────────────────────────────────────────────
 const ZERO=/(^|[^\d.,])0([.,]0+)?\s*(₫|đ\b)|\$\s?0([.,]00)?(?!\d)/;
 R('au-currency','Tiền đồng (VND)','Money in đồng (VND)','Chọn VND; Đi chợ, chi tiết nguyên liệu, Chi tiêu không còn “$”; đồ mua thêm chưa có giá không hiện 0; hoá đơn VND lưu được.','Choose VND; Shopping, an ingredient’s details and Spending show no “$”; an extra without a price shows no 0; a VND receipt saves.',async()=>{
  await part(aT('Cài đặt → Tiền tệ: VND','Settings → Currency: VND'),async()=>{currencyModal();await pick('#modal-root #currency-form [name="currency"]','VND');const b=find('#modal-root #currency-form button[type="submit"]')||find('#modal-root #currency-form button:not([type])');if(b)await tap(b);else (document.getElementById('currency-form') as HTMLFormElement).requestSubmit();await sleep(250);closeModal();
   expect(currentCurrency(state)==='VND',aT('Không đổi được sang VND.','Could not switch to VND.'))});
  await part(aT('Đi chợ: tiền theo đồng, không có “$”','Shopping: money in đồng, no “$”'),async()=>{await go('shopping');expect(!/\$/.test(mainText()),aT(`Đi chợ còn “$”: ${(mainText().match(/.{0,30}\$.{0,12}/)||[''])[0]}`,`Shopping still shows “$”: ${(mainText().match(/.{0,30}\$.{0,12}/)||[''])[0]}`))});
  await part(aT('Chi tiết một nguyên liệu: giá theo đồng','An ingredient’s details: price in đồng'),async()=>{await go('shopping');const b=find('#main [data-action="ingredient-detail"]');if(!b)skip(aT('Danh sách trống.','The list is empty.'));await tap(b!);await waitFor('#modal-root .modal');const t=modalText();closeModal();
   expect(!/\$/.test(t),aT(`Sheet còn “$”: ${(t.match(/.{0,30}\$.{0,12}/)||[''])[0]}`,`The sheet shows “$”: ${(t.match(/.{0,30}\$.{0,12}/)||[''])[0]}`));expect(!ZERO.test(t),aT(`Sheet ghi giá 0: ${(t.match(/.{0,30}0\s*₫.{0,5}/)||[''])[0]}`,`The sheet shows a price of 0: ${(t.match(/.{0,30}0\s*₫.{0,5}/)||[''])[0]}`))});
  await part(aT('Mua thêm, giá để trống → giá “chưa rõ”, không hiện 0','An extra without a price → unknown, never 0'),async()=>{await go('shopping');await tap('#main [data-action="add-extra"]');await waitFor('#modal-root #extra-form');await type('#modal-root #extra-name','Khăn giấy (thử)');await type('#modal-root #extra-amount','1');await pickUnit('#modal-root #extra-unit-btn','gói');await submit('extra-form');await sleep(200);
   const e=currentWeek().extras.find((x:any)=>x.name==='Khăn giấy (thử)');expect(e,aT('Không lưu được.','Not saved.'));expect(e.costUnknown===true,aT(`Giá để trống mà lưu thành ${e.cost}.`,`An empty price was saved as ${e.cost}.`));
   await go('shopping');const row=find(`#main [data-change="extra-done"][data-id="${e.id}"]`)?.closest('.shop-row') as HTMLElement|null;expect(row,aT('Không thấy trong danh sách.','Not on the list.'));expect(!ZERO.test(row!.innerText)&&!/\$/.test(row!.innerText),aT(`Dòng ghi giá: ${row!.innerText.replace(/\s+/g,' ')}`,`The row shows a price: ${row!.innerText.replace(/\s+/g,' ')}`))});
  await part(aT('Hoá đơn VND lưu được, Chi tiêu không có “$”','A VND receipt saves; Spending has no “$”'),async()=>{await enterReceipt(['CO.OP MART','TRUNG GA 10 QUA 3500.00','TOTAL 3500.00'].join('\n'));const r=await saveReceipt();try{closeModal()}catch{}expect(r.currency==='VND',aT(`Hoá đơn lưu theo ${r.currency}.`,`The receipt was saved in ${r.currency}.`));
   await go('expenses');expect(!/\$/.test(mainText()),aT(`Chi tiêu còn “$”: ${(mainText().match(/.{0,30}\$.{0,12}/)||[''])[0]}`,`Spending still shows “$”: ${(mainText().match(/.{0,30}\$.{0,12}/)||[''])[0]}`))})});

 // ── 5. a dish with its own yield, and guests (audit C1, C4, C7; rule 34) ────────────────────────────────────────────────
 R('au-yield','Món có khẩu phần riêng và khách','A dish with its own yield, and guests','Viết món cho 2 suất (600 g gà, 3 quả trứng); lên bữa tối mai; lượng đi chợ = định lượng × suất ÷ 2, trứng làm tròn quả; thêm khách lượng tăng theo; hơn 30 suất vẫn lưu được.','Write a dish for 2 (600 g chicken, 3 eggs); tomorrow’s dinner; amounts = recipe × portions ÷ 2, eggs whole; guests raise it; over 30 portions still saves.',async()=>{
  const chicken=idOf('Thịt gà','Gà'),egg=idOf('Trứng gà','Trứng'),d=addDays(today(),1);let r:any;ensureMenu(d);
  await part(aT('Viết món: 2 suất, 600 g thịt gà, 3 quả trứng','Write the dish: serves 2, 600 g chicken, 3 eggs'),async()=>{r=await writeDish('Gà hấp trứng 2 suất (thử)',[[chicken,600,'g'],[egg,3,ing(egg)[1]]],{yieldN:2});expect(familyYield(r)===2,aT(`Món lưu ${familyYield(r)} suất, không phải 2.`,`Saved for ${familyYield(r)}, not 2.`))});
  await part(aT('Bữa tối mai chỉ có món này (Bỏ hết món, rồi thêm)','Tomorrow’s dinner has only this dish (Clear, then add)'),async()=>{weekStart=planStartOf(state,d);await go('planner');weekStart=planStartOf(state,d);render();const c=find(`#main [data-fm="clear-meal"][data-date="${d}"][data-type="dinner"]`);if(c){await tap(c);await sleep(200)}else{mealOf(d,'dinner').recipes=[];save();render()}await addToMeal(d,'dinner',r);await everyoneHome(d,'dinner')});
  const check=async(label:string)=>{const m=mealOf(d,'dinner'),serv=mealServings(m,state),dish=m.recipes.find((x:any)=>x.id===r.id),f=dishFactor(m,dish),want=600*serv*f/2,got=+(mealIngredients(m,state)[chicken]||0);
   expect(near(got,want,1),aT(`${label}: thịt gà ${Math.round(got)} g, cần 600 × ${serv} ÷ 2 = ${Math.round(want)} g.`,`${label}: chicken ${got} g, expected ${want} g.`));
   const re=rowOf(egg,d,d);expect(re&&Number.isInteger(+(re.missing??re.needed))&&+(re.missing??re.needed)+1e-9>=3*serv*f/2-stockOf(egg),aT(`${label}: trứng trên danh sách ${re?re.missing:'?'} (cần tròn quả, ít nhất ${+(3*serv*f/2).toFixed(2)}).`,`${label}: eggs on the list ${re?re.missing:'?'} (whole, at least ${3*serv*f/2}).`))};
  await part(aT('Lượng = định lượng × suất ăn ÷ 2; trứng tròn quả','Amounts = recipe × portions ÷ 2; whole eggs'),()=>check(aT('Cả nhà','Family')));
  await part(aT('Thêm 2 người lớn khách → lượng tăng theo','2 adult guests → amounts rise'),async()=>{const s0=mealServings(mealOf(d,'dinner'),state);await guestsFor(d,'dinner','Khách ăn gà (thử)',1);expect(near(mealServings(mealOf(d,'dinner'),state),s0+2,0.01),aT('Suất ăn không tăng theo khách.','Portions did not follow the guests.'));await check(aT('Có khách','With guests'))});
  await part(aT('Khách đông (hơn 30 suất) vẫn lưu và mở lại được','Many guests (over 30 portions) still save and load'),async()=>{await guestsFor(d,'dinner','Tiệc lớn (thử)',30);const s=mealServings(mealOf(d,'dinner'),state);expect(s>30,aT(`Chỉ có ${s} suất.`,`Only ${s} portions.`));expect(validImport(clone(state)),aT(`Bữa ${s} suất làm dữ liệu không mở lại được.`,`A meal of ${s} portions makes the data fail to load.`));await check(aT('Tiệc lớn','Big party'))})});

 // ── 6. nothing chosen for the family (audit A3, A4, A15, C2, C3, C6, C12, C13, C25; rule 32) ──────────────────────────
 R('au-defaults','Không tự chọn thay nhà mình','Nothing chosen for the family','Thêm đồ vào tủ, mua thêm ở Đi chợ, dòng hoá đơn, dòng Viết món: chưa chọn thì không lưu “g”, $0 hay mục đầu danh sách; giá chưa biết không hiện $0.','Pantry food, an extra on Shopping, a receipt line, a recipe row: nothing the family did not choose is saved — no “g”, $0 or first item; an unknown price never shows $0.',async()=>{
  await part(aT('Tủ → Thêm thực phẩm: chưa chọn thì trống, không lưu','Pantry → Add: empty until chosen, nothing saved'),async()=>{await go('pantry');await tap('#main [data-action="add-stock"]');await waitFor('#modal-root #stock-form');const n0=state.pantry.length;
   expect(!(document.getElementById('stock-ing') as HTMLSelectElement).value,aT(`Nguyên liệu tự chọn sẵn “${(document.getElementById('stock-ing') as HTMLSelectElement).value}”.`,'An ingredient is chosen already.'));expect(!(document.getElementById('stock-place') as HTMLSelectElement).value,aT('Nơi cất tự chọn sẵn.','A place is chosen already.'));/* v1.7.19 re-check (B12): the unit is the shared picker's field now; it stays empty until an ingredient is chosen */expect(!(document.getElementById('stock-unit') as HTMLInputElement|null)?.value,aT('Đơn vị hiện sẵn khi chưa chọn nguyên liệu.','A unit shows before an ingredient is chosen.'));
   await type('#modal-root #stock-qty','2');await submit('stock-form');expect(state.pantry.length===n0&&find('#modal-root #stock-form'),aT('Chưa chọn nguyên liệu mà vẫn lưu.','Saved without an ingredient.'));closeModal()});
  await part(aT('Mua thêm: tên lạ, chưa chọn đơn vị → hỏi, không lưu “g”','Buy extra: an unknown name, no unit → asked, no “g”'),async()=>{await go('shopping');await tap('#main [data-action="add-extra"]');await waitFor('#modal-root #extra-form');const n0=currentWeek().extras.length;
   await type('#modal-root #extra-name','Đồ lạ chưa biết (thử)');await type('#modal-root #extra-amount','2');expect(!(document.getElementById('extra-unit') as HTMLInputElement).value,aT(`Đơn vị tự điền “${(document.getElementById('extra-unit') as HTMLInputElement).value}”.`,'A unit was filled in.'));
   await submit('extra-form');expect(currentWeek().extras.length===n0,aT('Chưa chọn đơn vị mà vẫn lưu.','Saved without a unit.'));expect(find('#modal-root #extra-unit-msg'),aT('Không nói phải chọn đơn vị.','Did not say to pick a unit.'));
   await pickUnit('#modal-root #extra-unit-btn','hộp');await submit('extra-form');await sleep(150);const e=currentWeek().extras.find((x:any)=>x.name==='Đồ lạ chưa biết (thử)');expect(e,aT('Không lưu được.','Not saved.'));
   expect(e.unit==='hộp'&&!/\bg\b/.test(e.qty),aT(`Lưu thành “${e.qty}”.`,`Saved as “${e.qty}”.`));expect(e.costUnknown===true,aT(`Giá để trống mà lưu ${e.cost}.`,`An empty price was saved as ${e.cost}.`));expect(!e.ingredient,aT(`Tự gắn với “${e.ingredient}”.`,`Linked to “${e.ingredient}” by itself.`));
   const row=find(`#main [data-change="extra-done"][data-id="${e.id}"]`)?.closest('.shop-row') as HTMLElement|null;expect(row&&!ZERO.test(row.innerText),aT(`Dòng ghi giá 0: ${row?.innerText.replace(/\s+/g,' ')}`,`The row shows a 0 price: ${row?.innerText.replace(/\s+/g,' ')}`))});
  await part(aT('Mua thêm: tên khớp nguyên liệu → gợi ý đúng đơn vị của nó','Buy extra: a known name → its own unit is suggested'),async()=>{const egg=idOf('Trứng gà','Trứng');await go('shopping');await tap('#main [data-action="add-extra"]');await waitFor('#modal-root #extra-form');await type('#modal-root #extra-name',String(ing(egg)[0]));await sleep(100);
   const u=(document.getElementById('extra-unit') as HTMLInputElement).value;closeModal();expect(u===ing(egg)[1],aT(`“${ing(egg)[0]}” gợi ý “${u}”, không phải “${ing(egg)[1]}”.`,`“${ing(egg)[0]}” suggests “${u}”, not “${ing(egg)[1]}”.`))});
  await part(aT('Hoá đơn: dòng không ghi lượng → lượng và đơn vị để trống','Receipt: a line without an amount → amount and unit stay empty'),async()=>{await enterReceipt(['ALDI','BREAD WHITE 3.50','TOTAL 3.50'].join('\n'));const line=document.querySelector('#modal-root .receipt-line') as HTMLElement;
   const u=(line.querySelector('.receipt-unit') as HTMLInputElement)?.value,q=(line.querySelector('.receipt-qty') as HTMLInputElement)?.value;expect(!u&&!q,aT(`Dòng “BREAD WHITE” tự điền ${q} ${u}.`,`“BREAD WHITE” got ${q} ${u} by itself.`));const r=await saveReceipt();try{closeModal()}catch{}
   const it=r.items.find((x:any)=>/BREAD/.test(x.label));expect(it&&!it.enteredUnit&&it.quantity==null,aT(`Lưu dòng bánh mì thành ${it?.quantity} ${it?.enteredUnit||''}.`,`The bread line was saved as ${it?.quantity} ${it?.enteredUnit||''}.`));expect(it.total===3.5,aT('Giá dòng bị đổi.','The line price changed.'))});
  await part(aT('Viết món: dòng mới chưa có đơn vị; tên khớp mới gợi ý','Write a recipe: a new row has no unit; a known name suggests one'),async()=>{await go('recipes');await tap('#main [data-fm="new"]');const form=await waitFor('#family-recipe-form');const li=form.querySelector('.rc-ing-row') as HTMLElement;const ub=li.querySelector('.rc-ing-unit') as HTMLElement;
   expect(!(ub.getAttribute('value')||(ub as any).value),aT(`Dòng mới có sẵn đơn vị “${ub.getAttribute('value')}”.`,`A new row has the unit “${ub.getAttribute('value')}”.`));setVal(li.querySelector('.rc-ing-name-input'),'Gia vị lạ (thử)');await sleep(120);expect(!(ub.getAttribute('value')||(ub as any).value),aT('Tên lạ mà đơn vị tự điền.','An unknown name got a unit.'));
   const egg=idOf('Trứng gà','Trứng');setVal(li.querySelector('.rc-ing-name-input'),String(ing(egg)[0]));await sleep(120);const v=ub.getAttribute('value')||(ub as any).value;closeModal();expect(!v||v===ing(egg)[1],aT(`“${ing(egg)[0]}” gợi ý “${v}”.`,`“${ing(egg)[0]}” suggests “${v}”.`))})});

 // ── 7–8. counts equal what they open; nothing opens empty without saying why (audit A1, A7, A12, A16, A19, C14; rule 31) ──
 const num=(t:string)=>{const m=String(t||'').match(/\((\d+)\)/)||String(t||'').match(/(\d+)/);return m?+m[1]:NaN};
 const emptyOk=(root:Element|null)=>!!root&&(root.textContent||'').trim().length>12&&!!root.querySelector('.btn,a.btn,button');
 async function countsCheck(){
  await part(aT('Đi chợ: “Đồ trong tủ (n)” mở đúng n món','Shopping: “Pantry (n)” opens n items'),async()=>{await go('shopping');const bs=[...document.querySelectorAll('#main [data-action="check-pantry"]')].filter(k.visible) as HTMLElement[];expect(bs.length,aT('Không có nút Đồ trong tủ.','No pantry button.'));
   const ns=bs.map(b=>num(b.textContent||''));expect(ns.every(n=>n===ns[0]),aT(`Hai nút ghi số khác nhau: ${ns.join(' / ')}.`,`The buttons show different numbers: ${ns.join(' / ')}.`));
   for(const b of bs){const n=num(b.textContent||'');await tap(b);await waitFor('#modal-root .modal');const got=document.querySelectorAll('#modal-root [data-change="skip-stock"],#modal-root .pantry-check-lot').length;const body=document.querySelector('#modal-root .modal-content');const ok=got===n&&(n>0||emptyOk(body));closeModal();
    expect(got===n,aT(`Nút ghi ${n} mà sheet có ${got} món.`,`The button says ${n}, the sheet lists ${got}.`));expect(ok,aT('Sheet trống mà không nói vì sao và làm gì.','An empty sheet without a reason or an action.'))}});
  await part(aT('Đi chợ: “n bữa sử dụng” mở đúng n bữa','Shopping: “used in n meals” lists n meals'),async()=>{await go('shopping');const bs=([...document.querySelectorAll('#main [data-action="ingredient-detail"]')] as HTMLElement[]).filter(k.visible).slice(0,4);
   if(!bs.length){expect(emptyOk(document.querySelector('#main .card.empty'))||/Lên thực đơn|Plan the menu|chưa có món|No dishes/i.test(mainText()),aT('Danh sách trống mà không nói vì sao.','An empty list without a reason.'));return}
   for(const b of bs){const n=num(b.querySelector('small')?.textContent||''),id=b.dataset.id;await tap(b);await waitFor('#modal-root .modal');const h=[...document.querySelectorAll('#modal-root h3')].find(x=>/Dùng cho|Used (in|for)/i.test(x.textContent||''));const list=(h?.nextElementSibling?.textContent||'').split(' · ').filter(x=>x.trim()).length;closeModal();
    expect(list===n,aT(`${ing(id!)?.[0]}: nút ghi ${n} bữa, sheet có ${list}.`,`${id}: the button says ${n} meals, the sheet lists ${list}.`))}});
  await part(aT('Món ăn: số trên các tab bằng số món hiện ra','Recipes: the numbers on the tabs equal the dishes shown'),async()=>{await go('recipes');for(const f of ['all','own','samples']){const tab=find(`#main [role="tab"][data-fm="${f}"]`);if(!tab)continue;const n=num(tab.textContent||'');await tap(tab,{still:true});await sleep(150);
    for(let i=0;i<40;i++){const more=find('#main [data-fm="load-more"]');if(!more)break;await tap(more,{still:true});await sleep(80)}const got=document.querySelectorAll('#main .lib-card').length;
    expect(got===n,aT(`Tab “${(tab.textContent||'').trim()}” ghi ${n} mà hiện ${got} món.`,`Tab “${(tab.textContent||'').trim()}” says ${n} but shows ${got}.`));if(!n)expect(emptyOk(document.querySelector('#main .lib-empty,#main .card.empty,#main .empty'))||!!find('#main [data-fm="samples"].btn,#main [data-fm="new"]'),aT('Tab trống mà không nói vì sao và làm gì.','An empty tab without a reason or an action.'))}});
  await part(aT('Tủ: số trên thẻ bằng số lô hiện ra','Pantry: the numbers on the cards equal the lots listed'),async()=>{await go('pantry');const cards=[...document.querySelectorAll('#main .stat-grid .card')] as HTMLElement[];if(!cards.length)return;const total=+(cards[0].querySelector('strong')?.textContent||'0');
   const all=find('#main [data-action="pantry-filter"][data-id="all"]');if(all)await tap(all,{still:true});const shown=document.querySelectorAll('#main .inventory-card').length,lots=state.pantry.filter((p:any)=>(p.qty>0||p.purchase?.amount>0)&&INGREDIENTS[p.ingredient]).length;
   expect(total===lots,aT(`Thẻ ghi ${total} lô, tủ có ${lots}.`,`The card says ${total} lots, the pantry has ${lots}.`));expect(shown<=total&&(total===0||shown>0),aT(`Thẻ ghi ${total} lô mà danh sách hiện ${shown} nhóm.`,`The card says ${total} lots but ${shown} groups are listed.`));
   if(!total)expect(emptyOk(document.querySelector('#main .card.empty'))||!!find('#main [data-action="add-stock"]'),aT('Tủ trống mà không nói làm gì.','An empty pantry without an action.'))});
  await part(aT('Hôm nay: không báo “đủ nguyên liệu” khi chưa có món','Today: no “everything in stock” when nothing is planned'),async()=>{await go('today');const planned=MEAL_TYPES.some((t:string)=>mealOf(selectedDate,t)?.recipes?.length);if(!planned)expect(!/đã đủ nguyên liệu|have everything/i.test(mainText()),aT('Chưa có món mà báo đã đủ nguyên liệu.','Says everything is in stock with nothing planned.'))});
  await part(aT('Chi tiêu: nút hoá đơn mở sheet có nội dung','Spending: the receipt buttons open a sheet with content'),async()=>{await go('expenses');const bs=([...document.querySelectorAll('#main [data-feature],#main [data-rl-open],#main [data-action="receipt-list"]')] as HTMLElement[]).filter(b=>k.visible(b)&&b.tagName==='BUTTON'&&!/receipt-new|receipt-save/.test(b.dataset.feature||'')).slice(0,4);
   for(const b of bs){await tap(b);await sleep(250);const body=document.querySelector('#modal-root .modal-content');if(!body)continue;const ok=(body.textContent||'').trim().length>12;closeModal();expect(ok,aT(`“${(b.textContent||'').trim().slice(0,40)}” mở sheet trống.`,`“${(b.textContent||'').trim().slice(0,40)}” opens an empty sheet.`))}})}
 R('au-counts','Số trên nút bằng nội dung (có dữ liệu)','Numbers equal what opens (with data)','Đồ trong tủ (n), “n bữa sử dụng”, tab Món ăn, thẻ trong Tủ: số trên nút bằng số món mở ra; tab, chip bấm không làm trang nhảy.','Pantry (n), “used in n meals”, Recipes tabs, Pantry cards: the number equals what opens; tabs and chips do not move the page.',async()=>{
  await part(aT('Tủ có vài lô (một lô ngăn đông)','A few pantry lots (one in the freezer)'),async()=>{const egg=idOf('Trứng gà','Trứng'),rice=idOf('Gạo');if(k.mode()==='sample'){state.pantry.push({id:'ap-c1',ingredient:egg,qty:6,place:'fridge',expiry:addDays(today(),2)},{id:'ap-c2',ingredient:rice,qty:2000,place:'dry',expiry:''});save();render()}});
  await countsCheck()});
 R('au-counts-empty','Số và sheet khi bếp còn trống','Numbers and sheets in an empty kitchen','Tủ trống, chưa có thực đơn, chưa có hoá đơn: mọi số là 0 và mỗi sheet trống nói vì sao, kèm việc cần làm.','Empty pantry, no menu, no receipts: every number is 0 and each empty sheet says why and what to do.',async()=>{
  await part(aT('Làm trống tủ, thực đơn, hoá đơn','Empty the pantry, the menu and the receipts'),async()=>{state.pantry=[];state.receipts=[];for(const w of Object.values(state.weeks) as any[]){w.extras=[];for(const day of Object.values(w.days||{}) as any[])for(const m of Object.values(day||{}) as any[])if(m&&Array.isArray((m as any).recipes)){(m as any).recipes=[];(m as any).cooked=false}}save();render()});
  await countsCheck();
  await part(aT('Đi chợ trống nói vì sao và mở được Thực đơn','An empty list says why and opens the menu'),async()=>{await go('shopping');const e=find('#main .card.empty');expect(e&&emptyOk(e),aT('Đi chợ trống mà không nói vì sao.','An empty list without a reason.'))})});

 // ── 9. extras: add, edit, remove with undo; a bought extra counts on the list (audit A2, A6, A8, B5, B7; decisions 12 Nov) ──
 R('au-extras','Đồ mua thêm: sửa, bỏ, hoàn tác, tính vào danh sách','Extras: edit, remove, undo, count on the list','Thêm “Giấy bạc”; sửa tên, lượng, giá; bỏ ra (hỏi trước) rồi Hoàn tác; mua thêm đúng nguyên liệu trên danh sách thì dòng đó ghi “Đủ”.','Add “Foil”; edit name, amount, price; remove (asked first) then Undo; an extra of an ingredient on the list makes that row say “Enough”.',async()=>{
  let id='';
  await part(aT('Thêm “Giấy bạc (thử)” 1 cuộn, 3,50','Add “Foil (test)” 1 roll, 3.50'),async()=>{await go('shopping');await tap('#main [data-action="add-extra"]');await waitFor('#modal-root #extra-form');await type('#modal-root #extra-name','Giấy bạc (thử)');await type('#modal-root #extra-amount','1');await pickUnit('#modal-root #extra-unit-btn','cuộn');
   const c=find('#modal-root #extra-form [name="cost"]');if(c)await type('#modal-root #extra-form [name="cost"]','3.5');await submit('extra-form');const e=currentWeek().extras.find((x:any)=>x.name==='Giấy bạc (thử)');expect(e,aT('Không lưu được.','Not saved.'));id=e.id;expect(e.qty==='1 cuộn'&&(!c||e.cost===3.5),aT(`Lưu thành ${e.qty} · ${e.cost}.`,`Saved as ${e.qty} · ${e.cost}.`))});
  await part(aT('Sửa: tên, lượng, giá','Edit: name, amount, price'),async()=>{await go('shopping');await tap(`#main [data-action="edit-extra"][data-id="${id}"]`);await waitFor('#modal-root #extra-form');await type('#modal-root #extra-name','Giấy bạc lớn (thử)');await type('#modal-root #extra-amount','2');const c=find('#modal-root #extra-form [name="cost"]');if(c)await type('#modal-root #extra-form [name="cost"]','6');await submit('extra-form');
   const e=currentWeek().extras.find((x:any)=>x.id===id);expect(e&&e.name==='Giấy bạc lớn (thử)'&&e.qty==='2 cuộn'&&(!c||e.cost===6),aT(`Sau khi sửa: ${JSON.stringify(e&&{name:e.name,qty:e.qty,cost:e.cost})}`,`After editing: ${JSON.stringify(e&&{name:e.name,qty:e.qty,cost:e.cost})}`));expect(currentWeek().extras.filter((x:any)=>/Giấy bạc/.test(x.name)).length===1,aT('Sửa lại tạo thêm một món mới.','Editing added a second item.'))});
  await part(aT('Bỏ khỏi giỏ: hỏi trước, “Giữ lại” không đổi gì','Remove: asked first, “Keep” changes nothing'),async()=>{await go('shopping');await tap(`#main [data-action="delete-extra"][data-id="${id}"]`);await waitFor('#modal-root [data-action="delete-extra-confirm"]');await tap('#modal-root [data-action="close-modal"]');await sleep(150);expect(currentWeek().extras.some((x:any)=>x.id===id),aT('“Giữ lại” mà vẫn bị bỏ.','“Keep” removed it.'))});
  await part(aT('Bỏ khỏi giỏ → Hoàn tác đưa lại y như cũ','Remove → Undo brings it back as it was'),async()=>{const before=JSON.stringify(currentWeek().extras.find((x:any)=>x.id===id));await tap(`#main [data-action="delete-extra"][data-id="${id}"]`);await tap('#modal-root [data-action="delete-extra-confirm"]');await sleep(200);expect(!currentWeek().extras.some((x:any)=>x.id===id),aT('Không bỏ được.','Not removed.'));
   await undo();const back=currentWeek().extras.find((x:any)=>x.id===id);expect(back&&JSON.stringify(back)===before,aT('Hoàn tác không đưa lại đúng món.','Undo did not bring the same item back.'))});
  await part(aT('Mua thêm đúng nguyên liệu trên danh sách → dòng đó ghi “Đủ”','An extra of a listed ingredient → that row says “Enough”'),async()=>{await go('shopping');const [a,b]=shopDates(),r=rowsOf(a,b).find((x:any)=>shoppingHasAmount(x)&&!x.skip&&!x.bought&&x.missing>0&&['g','ml'].includes(ing(x.id)[1]));if(!r)skip(aT('Danh sách không có món nào để thử.','Nothing on the list to try.'));
   const need=Math.ceil(r.missing),u=ing(r.id)[1];await tap('#main [data-action="add-extra"]');await waitFor('#modal-root #extra-form');const cat=find('#modal-root #extra-catalog-ing');if(cat)await pick('#modal-root #extra-catalog-ing',r.id);await type('#modal-root #extra-name',String(ing(r.id)[0]));await type('#modal-root #extra-amount',String(need));
   if((document.getElementById('extra-unit') as HTMLInputElement).value!==u)await pickUnit('#modal-root #extra-unit-btn',u);await submit('extra-form');const e=currentWeek().extras.find((x:any)=>x.ingredient===r.id);expect(e,aT('Món mua thêm không gắn với nguyên liệu trên danh sách.','The extra is not linked to the listed ingredient.'));
   await go('shopping');await tap(`#main [data-change="extra-done"][data-id="${e.id}"]`);await sleep(250);if(find('#modal-root .modal'))closeModal();
   const r2=rowsOf(a,b).find((x:any)=>x.id===r.id);expect(r2?.boughtByExtra,aT(`${ing(r.id)[0]}: đã mua ${need} ${u} ở đồ dùng khác mà dòng chưa đủ.`,`${r.id}: ${need} ${u} bought as an extra but the row is not covered.`));
   const box=find(`#main input[data-change="bought"][data-id="${r.id}"]`),txt=(box?.closest('.shop-row') as HTMLElement)?.innerText||'';expect(/Đủ|Enough/.test(txt),aT(`Dòng ${ing(r.id)[0]} không ghi “Đủ”: ${txt.replace(/\s+/g,' ').slice(0,80)}`,`The row does not say “Enough”: ${txt.replace(/\s+/g,' ').slice(0,80)}`))})});

 // ── 10. the dish sheet and removing dishes (audit A13, A14, A21; decision “Dish sheet”, 12 Nov) ─────────────────────────
 const footerActs=()=>[...document.querySelectorAll('#modal-root .modal-footer [data-action]')].map(b=>(b as HTMLElement).dataset.action).filter(a=>a!=='close-modal');
 R('au-dish','Sheet món ăn và bỏ món có hoàn tác','The dish sheet, and removing with undo','Bỏ một món (×) và “Bỏ hết món” đều Hoàn tác được; sheet món từ bữa: Nấu món này · Sửa món · Bỏ khỏi bữa; từ Kho món: Thêm vào bữa · Sửa món · Xoá khỏi kho (Hoàn tác); món tham khảo: Ẩn khỏi kho rồi Hiện lại.','The dish × and “Clear meal” both undo; from a meal: Cook this · Edit · Take off; from the library: Add to a meal · Edit · Delete (undo); a catalogue dish: Hide, then Show again.',async()=>{
  const d=addDays(today(),1);ensureMenu(d);const t=MEAL_TYPES.find((x:string)=>(mealOf(d,x)?.recipes?.length||0)>=2&&!mealOf(d,x).cooked)||MEAL_TYPES.find((x:string)=>mealOf(d,x)?.recipes?.length&&!mealOf(d,x).cooked);if(!t)skip(aT('Ngày mai chưa có bữa nào có món.','No meal with dishes tomorrow.'));
  const ids=()=>mealOf(d,t).recipes.map((x:any)=>x.id).join(',');const openPlanner=async()=>{weekStart=planStartOf(state,d);selectedDate=d;await go('planner');weekStart=planStartOf(state,d);render();await sleep(100)};
  // the dish row itself goes away, so the page-still check (rule 24) follows the meal card that holds it
  const cardTop=()=>find(`#main .family-meal-card[data-meal-date="${d}"][data-meal-type="${t}"]`)?.getBoundingClientRect().top??NaN;
  const stillCard=(y0:number,what:string)=>{const moved=Math.round(cardTop()-y0);expect(Math.abs(moved)<=2,aT(`Bấm “${what}” làm thẻ bữa nhảy ${moved}px.`,`Tapping “${what}” moved the meal card by ${moved}px.`))};
  await part(aT('Bỏ một món (×) → Hoàn tác','Remove one dish (×) → Undo'),async()=>{await openPlanner();const before=ids();const y0=cardTop();await tap(`#main [data-fm="remove-dish"][data-date="${d}"][data-type="${t}"][data-index="0"]`);stillCard(y0,'×');expect(ids()!==before,aT('Bấm × mà món vẫn còn.','The × did not remove the dish.'));await undo();expect(ids()===before,aT(`Hoàn tác xong bữa có ${ids()}, cần ${before}.`,`After undo the meal has ${ids()}, expected ${before}.`))});
  await part(aT('“Bỏ hết món” → Hoàn tác','“Clear meal” → Undo'),async()=>{await openPlanner();const before=ids();const y0=cardTop();await tap(`#main [data-fm="clear-meal"][data-date="${d}"][data-type="${t}"]`);stillCard(y0,aT('Bỏ hết món','Clear meal'));await sleep(150);if(find('#modal-root [data-action="confirm-ok"],#modal-root .btn.danger'))await tap((find('#modal-root [data-action="confirm-ok"]')||find('#modal-root .btn.danger'))!);expect(!mealOf(d,t).recipes.length,aT('“Bỏ hết món” không bỏ hết.','“Clear meal” left dishes.'));await undo();expect(ids()===before,aT('Hoàn tác không đưa lại các món.','Undo did not bring the dishes back.'))});
  await part(aT('Sheet món từ bữa: Nấu món này · Sửa món · Bỏ khỏi bữa','From a meal: Cook this · Edit · Take off'),async()=>{await openPlanner();await tap(`#main [data-fm="recipe-snapshot"][data-date="${d}"][data-type="${t}"][data-index="0"]`);await waitFor('#modal-root .modal-footer');const a=footerActs();closeModal();
   expect(['start-cooking','dish-edit','dish-remove-meal'].every(x=>a.includes(x))&&a.length===3,aT(`Sheet món từ bữa có: ${a.join(', ')}.`,`From a meal the sheet has: ${a.join(', ')}.`))});
  await part(aT('“Bỏ khỏi bữa” → Hoàn tác','“Take off” → Undo'),async()=>{await openPlanner();const before=ids();await tap(`#main [data-fm="recipe-snapshot"][data-date="${d}"][data-type="${t}"][data-index="0"]`);await tap('#modal-root [data-action="dish-remove-meal"]');await sleep(200);expect(ids()!==before,aT('Món vẫn còn trong bữa.','The dish is still on the meal.'));await undo();expect(ids()===before,aT('Hoàn tác không đưa món lại vào bữa.','Undo did not put the dish back.'))});
  await part(aT('“Sửa món” từ bữa mở trình viết món với đúng món','“Edit” from a meal opens the editor on that dish'),async()=>{await openPlanner();const dish=mealOf(d,t).recipes[0];await tap(`#main [data-fm="recipe-snapshot"][data-date="${d}"][data-type="${t}"][data-index="0"]`);await tap('#modal-root [data-action="dish-edit"]');const f=await waitFor('#family-recipe-form');expect((f.querySelector('[name="name"]') as HTMLInputElement).value===dish.name,aT('Trình viết món mở món khác.','The editor opened another dish.'));closeModal()});
  let own:any=null;
  await part(aT('Sheet món từ Kho món (món của nhà): Thêm vào bữa · Sửa món · Xoá khỏi kho','From the library (family dish): Add to a meal · Edit · Delete'),async()=>{own=state.recipes.find((r:any)=>ownRecipe(r));if(!own){const src=clone(state.recipes.find((r:any)=>r.ingredients?.length));own={...src,id:'ap-own-'+Date.now().toString(36),name:'Món nhà mình (thử)',custom:true,origin:'family'};state.recipes.push(own);save()}
   showRecipe(own.id);await waitFor('#modal-root .modal-footer');const a=footerActs();closeModal();expect(['add-to-meal','dish-edit','dish-delete'].every(x=>a.includes(x))&&a.length===3,aT(`Sheet món của nhà có: ${a.join(', ')}.`,`The family dish sheet has: ${a.join(', ')}.`))});
  await part(aT('“Xoá khỏi kho” → Hoàn tác','“Delete” → Undo'),async()=>{await go('recipes');showRecipe(own.id);await tap('#modal-root [data-action="dish-delete"]');await sleep(200);expect(!state.recipes.some((r:any)=>r.id===own.id),aT('Món vẫn còn trong kho.','The dish is still in the library.'));await undo();expect(state.recipes.some((r:any)=>r.id===own.id),aT('Hoàn tác không đưa món lại vào kho.','Undo did not bring the dish back.'))});
  await part(aT('Món tham khảo: “Ẩn khỏi kho”, rồi “Hiện lại”','Catalogue dish: “Hide”, then “Show again”'),async()=>{const cat=state.recipes.find((r:any)=>!ownRecipe(r)&&!recipeHidden(state,r.id));if(!cat)skip(aT('Không có món tham khảo.','No catalogue dish.'));await go('recipes');showRecipe(cat.id);await waitFor('#modal-root .modal-footer');const a=footerActs();
   expect(['add-to-meal','dish-edit','dish-hide'].every(x=>a.includes(x))&&a.length===3,aT(`Sheet món tham khảo có: ${a.join(', ')}.`,`The catalogue dish sheet has: ${a.join(', ')}.`));await tap('#modal-root [data-action="dish-hide"]');await sleep(200);expect(recipeHidden(state,cat.id)&&state.recipes.some((r:any)=>r.id===cat.id),aT('Ẩn mà món bị xoá hoặc chưa ẩn.','Hiding deleted the dish or did not hide it.'));
   showRecipe(cat.id);await tap('#modal-root [data-action="dish-unhide"]');await sleep(200);expect(!recipeHidden(state,cat.id),aT('“Hiện lại” không hiện món.','“Show again” did not show it.'));try{closeModal()}catch{}})});

 // ── 11. spoon and bowl amounts are notes; the app still says whether it is in the pantry (decision 12 Nov) ───────────────
 R('au-spoon','Gia vị theo muỗng là ghi chú','Spoon amounts are notes','Món có “2 muỗng canh nước mắm”: không cộng vào đi chợ, nhưng Đi chợ nói còn trong tủ hay phải mua; thêm vào tủ thì đổi thành “còn trong tủ”.','A dish with “2 tbsp fish sauce”: not added to shopping, but Shopping says whether it is in the pantry; after adding it to the pantry it says so.',async()=>{
  const fish=idOf('Nước mắm'),chicken=idOf('Thịt gà','Gà'),d=addDays(today(),1);let r:any,n0=0;ensureMenu(d);
  await part(aT('Viết món có 2 muỗng canh nước mắm','Write a dish with 2 tbsp fish sauce'),async()=>{r=await writeDish('Gà rim mắm (thử)',[[chicken,300,'g'],[fish,2,'muỗng canh']],{yieldN:4});expect(!r.ingredients.some((i:any)=>i.id===fish&&i.qty>0&&!(typeof isSpoonUnit==='function'&&isSpoonUnit(i.unit))),aT('Muỗng canh bị lưu như lượng đi chợ.','The spoon amount was saved as a shopping amount.'))});
  // the list with the dish equals the list of the same menu with the dish's spoon line taken out (other dishes may use fish sauce
  // by the ml, and the family's own copy may have people who have not answered yet — both stay as they are on each side)
  await part(aT('Lên bữa tối mai: nước mắm không cộng vào đi chợ','Tomorrow’s dinner: fish sauce is not added to shopping'),async()=>{await everyoneHome(d,'dinner');await addToMeal(d,'dinner',r);await everyoneHome(d,'dinner');
   const S=planStartOf(state,d),E=addDays(S,6),with1=+(rowOf(fish,S,E)?.needed||0),c=clone(state),cm=dayAt(c,d).dinner;for(const x of cm.recipes)if(x.id===r.id){x.ingredients=(x.ingredients||[]).filter((i:any)=>i.id!==fish);x.missingIngredients=(x.missingIngredients||[]).filter((l:string)=>!/mắm|fish/i.test(l))}
   const without=+(shopping(c,planWeek(c,S),S,E).find((x:any)=>x.id===fish)?.needed||0);n0=without;expect(near(with1,without,0.01),aT(`Nước mắm trên danh sách: ${Math.round(without)} → ${Math.round(with1)} vì món có 2 muỗng canh.`,`Fish sauce on the list: ${without} → ${with1} because of the 2 tbsp.`))});
  const status=async()=>{selectedDate=d;weekStart=planStartOf(state,d);await go('shopping');weekStart=planStartOf(state,d);render();const li=[...document.querySelectorAll('#main .shop-seasoning li')].find(x=>(x.textContent||'').includes(String(typeof shopIngName==='function'?shopIngName(fish):ing(fish)[0])));return (li as HTMLElement)?.innerText||''};
  await part(aT('Đi chợ: ghi “hết trong tủ · nhớ mua”','Shopping: says “none in the pantry · remember to buy”'),async()=>{state.pantry=state.pantry.filter((p:any)=>p.ingredient!==fish);save();const s=await status();expect(s,aT('Đi chợ không nhắc nước mắm.','Shopping does not mention fish sauce.'));expect(/hết trong tủ|none in the pantry/.test(s),aT(`Ghi: “${s}”.`,`Says: “${s}”.`))});
  await part(aT('Thêm nước mắm vào tủ → “còn trong tủ”','Fish sauce in the pantry → “in the pantry”'),async()=>{await go('pantry');await tap('#main [data-action="add-stock"]');await waitFor('#modal-root #stock-form');await pick('#modal-root #stock-ing',fish);await type('#modal-root #stock-qty','500');if(!(document.getElementById('stock-place') as HTMLSelectElement).value)await pick('#modal-root #stock-place','dry');await submit('stock-form');await waitGone('#modal-root #stock-form',4000);
   const s=await status();expect(/còn trong tủ|in the pantry/.test(s)&&!/hết|none/.test(s),aT(`Ghi: “${s}”.`,`Says: “${s}”.`))})});

 // ── 12. a receipt's pantry lots get an editable, suggested use-by (decision 12 Nov) ────────────────────────────────────
 R('au-useby','Hạn dùng gợi ý cho đồ từ hoá đơn','Suggested use-by for receipt lots','Hoá đơn có tôm ngoài danh sách: bước kiểm tra hiện hạn dùng ước tính, sửa được; lô trong tủ giữ đúng ngày đã sửa.','A receipt with prawns not on the list: the check step shows an estimated, editable use-by; the pantry lot keeps the edited date.',async()=>{
  const prawn=idOf('Tôm');let want='';
  await part(aT('Hoá đơn: 500 g tôm (ngoài danh sách)','Receipt: 500 g prawns (not on the list)'),async()=>{for(const w of Object.values(state.weeks) as any[])for(const day of Object.values(w.days||{}) as any[])for(const m of Object.values(day||{}) as any[])if(m&&Array.isArray((m as any).recipes))(m as any).recipes=(m as any).recipes.filter((x:any)=>!(x.ingredients||[]).some((i:any)=>i.id===prawn));save();
   await enterReceipt(['WOOLWORTHS','PRAWNS RAW 500G 12.90','TOTAL 12.90'].join('\n'),{match:[[/PRAWN/i,prawn,'tom']]});await saveReceipt()});
  await part(aT('Bước kiểm tra: hạn dùng ước tính, sửa được','Check step: an estimated use-by you can change'),async()=>{const g=await waitFor(`#modal-root [data-rlx-row="${prawn}"]`,4000);const box=find('#modal-root .rc-useby input[type="date"]') as HTMLInputElement|undefined;expect(box,aT('Không có ô hạn dùng.','No use-by field.'));
   expect(box!.value&&box!.value>=today(),aT(`Hạn dùng gợi ý “${box!.value}”.`,`Suggested use-by “${box!.value}”.`));expect(/ước tính|estimate/i.test((box!.closest('.rc-useby') as HTMLElement).innerText),aT('Không ghi là ước tính.','Not marked as an estimate.'));want=addDays(today(),3);setVal(box,want);void g});
  await part(aT('“Cập nhật đi chợ & kho” → lô tôm giữ ngày đã sửa','“Update shopping & pantry” → the prawn lot keeps the edited date'),async()=>{const s0=state.pantry.filter((p:any)=>p.ingredient===prawn).length;await tap('#modal-root [data-rui="apply"]');await sleep(300);try{closeModal()}catch{}const lots=state.pantry.filter((p:any)=>p.ingredient===prawn);
   expect(lots.length>s0,aT('Tôm không vào tủ.','The prawns did not go into the pantry.'));const lot=lots[lots.length-1];expect(lot.expiry===want,aT(`Lô tôm hạn ${lot.expiry||'trống'}, cần ${want}.`,`The prawn lot's use-by is ${lot.expiry||'empty'}, not ${want}.`))})});

 // ── 13. meal times in “Giờ ăn” drive the cooking time; “Chưa đặt” means no reminder (decision 12 Nov) ──────────────────
 R('au-mealtimes','Giờ ăn và giờ bắt đầu nấu','Meal times and when to start cooking','Bếp của nhà mình → Giờ ăn: bỏ giờ bữa sáng (“Chưa đặt”), trưa 12:30, tối 18:45; bữa có giờ thì có giờ bắt đầu nấu, bữa chưa đặt thì không nhắc; Nhắc nhở đọc cùng giờ.','My kitchen → Meal times: clear breakfast (“Not set”), lunch 12:30, dinner 18:45; a meal with a time gets a start time, one without gets no reminder; Reminders read the same times.',async()=>{
  const d=today();ensureMenu(d);
  await part(aT('Bếp của nhà mình → Giờ ăn: sáng “Chưa đặt”, trưa 12:30, tối 18:45','My kitchen → Meal times: breakfast not set, lunch 12:30, dinner 18:45'),async()=>{state.preferences.enabledMeals=['breakfast','lunch','dinner'];kitchenModal('mealtimes');await waitFor('#modal-root #meal-times-form');
   const c=find('#modal-root [data-mt="clear"][data-type="breakfast"]');if(c&&!(c as HTMLButtonElement).disabled)await tap(c,{still:true});await type('#modal-root #mt-lunch','12:30');await type('#modal-root #mt-dinner','18:45');
   expect(/Chưa đặt|Not set/.test((find('#modal-root #mt-breakfast-state') as HTMLElement)?.innerText||''),aT('Bữa sáng không ghi “Chưa đặt”.','Breakfast does not say “Not set”.'));
   const save=find('#modal-root [data-action="submit-form"][data-id*="meal-times-form"]')||find('#modal-root [data-mt="save"]');expect(save,aT('Không có nút Lưu giờ ăn.','No save button for meal times.'));await tap(save!);await sleep(250);try{closeModal()}catch{}
   expect(mealTimeOf(state,'breakfast')===''&&mealTimeOf(state,'lunch')==='12:30'&&mealTimeOf(state,'dinner')==='18:45',aT(`Giờ đã lưu: sáng “${mealTimeOf(state,'breakfast')}”, trưa ${mealTimeOf(state,'lunch')}, tối ${mealTimeOf(state,'dinner')}.`,`Saved: breakfast “${mealTimeOf(state,'breakfast')}”, lunch ${mealTimeOf(state,'lunch')}, dinner ${mealTimeOf(state,'dinner')}.`))});
  await part(aT('Bữa có giờ có giờ bắt đầu nấu; bữa “Chưa đặt” không nhắc','A meal with a time gets a start time; “Not set” gets none'),async()=>{for(const t of ['breakfast','lunch','dinner']){const m=mealOf(d,t);if(!m?.recipes?.length||m.cooked)continue;const ct=cookTiming(state,m,mealTimeOf(state,t));
    if(t==='breakfast')expect(!ct,aT('Bữa sáng chưa đặt giờ mà vẫn có giờ nấu.','Breakfast has no time but still gets a cooking time.'));else expect(ct&&(ct.start||ct.early||ct.longest===null),aT(`${t}: có giờ ăn mà không có giờ bắt đầu nấu.`,`${t}: a meal time but no start time.`))}
   await go('today');const card=(t:string)=>find(`#main .family-meal-card[data-meal-date="${d}"][data-meal-type="${t}"] .meal-label`)?.textContent||'';if(mealOf(d,'lunch')?.recipes?.length)expect(/12:30/.test(card('lunch')),aT('Thẻ bữa trưa không ghi 12:30.','The lunch card does not show 12:30.'));if(mealOf(d,'breakfast')?.recipes?.length)expect(!/\d\d:\d\d/.test(card('breakfast')),aT('Thẻ bữa sáng ghi giờ dù chưa đặt.','The breakfast card shows a time although none is set.'))});
  await part(aT('Nhắc nhở đọc cùng giờ ăn','Reminders read the same meal times'),async()=>{const host=document.createElement('div');host.innerHTML=mealTimesSummaryHtml();const rows=[...host.querySelectorAll('.meal-times-list li')].map(li=>(li as HTMLElement).textContent||'');
   expect(rows.some(x=>/(sáng|Breakfast).*(Chưa đặt|Not set)/i.test(x))&&rows.some(x=>/12:30/.test(x))&&rows.some(x=>/18:45/.test(x)),aT(`Nhắc nhở ghi: ${rows.join(' | ')}`,`Reminders show: ${rows.join(' | ')}`))})});
 // ── 14. a phone that is not on the family's time (rule 34; owner, 13 Nov 2026: “do everything in this round”) ─────────────
 // The dates and times the app shows are compared with the family's own zone (Sydney unless the family chose another), worked
 // out here on their own, never with the app's helpers. Whatever zone the phone is really in, while this scenario runs the
 // browser's default zone — what Intl and toLocale…String use when no zone is given — is moved to Los Angeles (or Kiritimati), a
 // zone whose date differs from the family's at that moment, so a screen that formats with the phone's zone shows another day.
 // (Date's own clock functions are left alone: changing them without changing date arithmetic would test the fake, not the app.
 // The browser suite also runs this scenario on a phone really set to Los Angeles time.) Everything is put back afterwards.
 const RealDTF=Intl.DateTimeFormat,RealDate:any={};for(const n of ['toLocaleDateString','toLocaleTimeString','toLocaleString'])RealDate[n]=(Date.prototype as any)[n];
 const famZone=()=>(state as any).preferences?.timezone||'Australia/Sydney';
 const zoneParts=(zone:string,at:Date=new Date())=>{const p:any=Object.fromEntries(new RealDTF('en-US',{timeZone:zone,year:'numeric',month:'numeric',day:'numeric',hour:'numeric',minute:'numeric',hourCycle:'h23'}).formatToParts(at).map((x:any)=>[x.type,x.value]));return{y:+p.year,m:+p.month,d:+p.day,h:+p.hour%24,min:+p.minute}};
 const zoneDate=(zone:string,at:Date=new Date())=>{const p=zoneParts(zone,at);return `${p.y}-${String(p.m).padStart(2,'0')}-${String(p.d).padStart(2,'0')}`};
 const zoneHM=(zone:string,at:Date=new Date())=>{const p=zoneParts(zone,at);return `${String(p.h).padStart(2,'0')}:${String(p.min).padStart(2,'0')}`};
 const realZone=()=>{try{return new RealDTF().resolvedOptions().timeZone}catch{return''}};
 function phoneIn(zone:string){const D:any=Date.prototype,I:any=Intl;
  const Fake:any=function(locales?:any,opts?:any){return new RealDTF(locales,{...(opts||{}),timeZone:opts?.timeZone||zone})};Fake.prototype=RealDTF.prototype;Fake.supportedLocalesOf=RealDTF.supportedLocalesOf;I.DateTimeFormat=Fake;
  for(const n of ['toLocaleDateString','toLocaleTimeString','toLocaleString'])D[n]=function(l?:any,o?:any){return RealDate[n].call(this,l,{...(o||{}),timeZone:o?.timeZone||zone})};
  return()=>{I.DateTimeFormat=RealDTF;for(const [n,f] of Object.entries(RealDate))D[n]=f}}
 R('au-phone-tz','Điện thoại không để giờ Sydney','A phone not on Sydney time','Cho máy dùng giờ Los Angeles (hoặc Kiritimati) vào lúc ngày ở đó khác ngày của nhà; Thực đơn, Hôm nay, hoá đơn mới, đồ cất vào tủ và giờ hiển thị vẫn theo giờ của nhà (giờ Sydney nếu nhà chưa chọn giờ khác).','Put the phone on Los Angeles (or Kiritimati) time while its date differs from the family’s; the menu, Today, a new receipt, food put in the pantry and the times shown still follow the family’s zone (Sydney unless the family chose another).',async()=>{
  const fam=famZone(),now=new Date(),phone=['America/Los_Angeles','Pacific/Kiritimati','Etc/GMT+12'].find(z=>zoneDate(z,now)!==zoneDate(fam,now))||'America/Los_Angeles';
  const famDay=()=>zoneDate(fam);let restore:any=null;
  try{
   await part(aT(`Máy dùng giờ ${phone} (máy đang để ${realZone()}); ngày của nhà (${fam}) khác ngày trên máy`,`The phone uses ${phone} time (it is set to ${realZone()}); the family’s date (${fam}) differs from the phone’s`),async()=>{restore=phoneIn(phone);
    /* deliberately the phone's own zone (no timeZone): this checks that the phone now uses the zone set above */const at0=new Date(),dev=at0.toLocaleDateString('en-CA');
    expect(new Intl.DateTimeFormat().resolvedOptions().timeZone===phone&&dev===zoneDate(phone),aT(`Máy chưa dùng giờ ${phone} (${dev}).`,`The phone is not using ${phone} time (${dev}).`));
    expect(dev!==famDay(),aT('Ngày trên máy trùng ngày của nhà; không kiểm tra được.','The phone’s date is the family’s; nothing to check.'))});
   await part(aT('Thực đơn → “Tuần này”: “Hôm nay” là ngày của nhà','Menu → “This week”: “Today” is the family’s date'),async()=>{await go('planner');weekStart=planStartOf(state,addDays(famDay(),14));render();await sleep(100);const wn=find('#main [data-action="week-now"]');if(wn)await tap(wn,{still:true});else{selectedDate=sydneyDate();weekStart=planStartOf(state,selectedDate);render()}await sleep(150);
    const marked=[...document.querySelectorAll('#main .plan-day.is-today')].map(x=>(x as HTMLElement).dataset.planDay||(x as HTMLElement).querySelector('[data-date]')?.getAttribute('data-date')||'?');
    expect(marked.length===1&&marked[0]===famDay(),aT(`Thực đơn đánh dấu hôm nay là ${marked.join(', ')||'không ngày nào'}, cần ${famDay()}.`,`The menu marks ${marked.join(', ')||'no day'} as today, not ${famDay()}.`));
    expect(weekStart===planStartOf(state,famDay()),aT(`“Tuần này” mở tuần ${weekStart}, cần tuần có ${famDay()}.`,`“This week” opened the week of ${weekStart}, not the one holding ${famDay()}.`))});
   await part(aT('Hôm nay: ngày được đánh dấu là ngày của nhà','Today: the marked day is the family’s date'),async()=>{await go('today');await sleep(120);
    const t=find('#main .day-strip .day.today') as HTMLElement|undefined;
    expect(t&&t.dataset.date===famDay(),aT(`Dải ngày đánh dấu hôm nay là ${t?.dataset.date||'không ngày nào'}, cần ${famDay()}.`,`The day strip marks ${t?.dataset.date||'no day'} as today, not ${famDay()}.`))});
   await part(aT('Hoá đơn mới ghi ngày của nhà','A new receipt is dated with the family’s date'),async()=>{await go('expenses');const nb=find('[data-feature="receipt-new"]');if(nb)await tap(nb);else newReceipt();const box=await waitFor('#modal-root #receipt-date') as HTMLInputElement;
    const v=box.value;try{closeModal()}catch{}expect(v===famDay(),aT(`Hoá đơn mới ghi ngày ${v}, cần ${famDay()}.`,`The new receipt says ${v}, not ${famDay()}.`))});
   await part(aT('Cất đồ vào tủ: ngày cất là ngày của nhà','Food put in the pantry: stored on the family’s date'),async()=>{const egg=idOf('Trứng gà','Trứng');await go('pantry');await tap('#main [data-action="add-stock"]');await waitFor('#modal-root #stock-form');await pick('#modal-root #stock-ing',egg);await type('#modal-root #stock-qty','6');if(!(document.getElementById('stock-place') as HTMLSelectElement).value)await pick('#modal-root #stock-place','fridge');
    const n0=state.pantry.length;await submit('stock-form');await waitGone('#modal-root #stock-form',4000);const lot:any=state.pantry.length>n0?state.pantry[state.pantry.length-1]:null;
    expect(lot&&lot.storedOn===famDay(),aT(`Lô trứng ghi ngày cất ${lot?.storedOn||'trống'}, cần ${famDay()}.`,`The egg lot says stored on ${lot?.storedOn||'nothing'}, not ${famDay()}.`))});
   await part(aT('Giờ và ngày hiển thị, giờ nhắc nấu theo giờ của nhà','Times and dates shown, and the reminder clock, follow the family’s zone'),async()=>{const at=new Date(),want=zoneHM(fam,at),p=zoneParts(fam,at),shown=appTimeLabel(at,{date:false}),dl=appTimeLabel(at,{time:false});
    expect(shown===want,aT(`Giờ hiển thị ${shown}, cần ${want} (${fam}).`,`Time shown ${shown}, not ${want} (${fam}).`));
    expect(dl===`${p.d}/${p.m}`,aT(`Ngày hiển thị ${dl}, cần ${p.d}/${p.m}.`,`Date shown ${dl}, not ${p.d}/${p.m}.`));
    expect(Math.abs(familyClockMinute(at)-(p.h*60+p.min))<=1,aT('Giờ nhắc nấu đang theo giờ trên máy.','The cooking-reminder clock follows the phone.'))});
  }finally{if(restore)restore();try{render()}catch{}}});
})();
